@app.get("/todos", response_model=list[TodoPublic])
def list_todos(session: SessionDep, offset: int = Query(default=0, ge=0),
               limit: int = Query(default=10, ge=1, le=100)):
    return session.exec(select(Todo).offset(offset).limit(limit)).all()

@app.get("/todos/{todo_id}", response_model=TodoPublic)
def read_todo(todo_id: int, session: SessionDep):
    todo = session.get(Todo, todo_id)
    if todo is None:
        raise HTTPException(status_code=404, detail="Todo not found")
    return todo

@app.patch("/todos/{todo_id}", response_model=TodoPublic)
def update_todo(todo_id: int, changes: TodoUpdate, session: SessionDep):
    todo = session.get(Todo, todo_id)
    if todo is None:
        raise HTTPException(status_code=404, detail="Todo not found")
    todo.sqlmodel_update(changes.model_dump(exclude_unset=True))
    session.add(todo)
    session.commit()
    session.refresh(todo)
    return todo

@app.delete("/todos/{todo_id}", status_code=204)
def delete_todo(todo_id: int, session: SessionDep):
    todo = session.get(Todo, todo_id)
    if todo is None:
        raise HTTPException(status_code=404, detail="Todo not found")
    session.delete(todo)
    session.commit()

